ctrls = [
    np.array([-0.510, -0.435, -0.837,  2.041,  0.004,  0.808, -0.305, -0.951,  2.078, -0.778, -0.043,  1.235,  0.149, -0.010,  0.452,  0.960,  0.335,  0.591,  0.637]),
