    np.array([-1.036,  0.202, -0.449,  1.287, -0.174,  1.081, -0.486,  0.538,  0.420, -1.194,  0.144,  0.200,  0.105, -0.344,  0.334,  0.481, -0.306, -0.949,  1.373]),
]
steps=[60,103,70]
# mappings for mirror
swap = {0:5,1:6,2:7,3:8,4:9,5:0,6:1,7:2,8:3,9:4,11:15,12:16,13:17,14:18,15:11,16:12,17:13,18:14}
neg_after_swap = {0,1,5,6,10,13,17}  # yaw/roll-ish; torso yaw and hip/shoulder yaws
# Actually 0/1 hip yaw/roll and 13/17 shoulder yaw? torso yaw 10 no.
# We'll try several transforms.
transforms=[]
# identity, swapped, swapped+negate yaw-ish, reversed phases, reversed+swap etc.
for mode in range(6):
    if mode==0:
        tc = ctrls
    elif mode==1:
        tc = [c.copy() for c in ctrls[::-1]]
    elif mode==2:
        tc = []
        for c in ctrls:
            d = c.copy()
            for a,b in [(0,5),(1,6),(2,7),(3,8),(4,9),(11,15),(12,16),(13,17),(14,18)]:
                d[a], d[b] = c[b], c[a]
            tc.append(d)
    elif mode==3:
        tc=[]
        for c in ctrls[::-1]:
            d = c.copy()
            for a,b in [(0,5),(1,6),(2,7),(3,8),(4,9),(11,15),(12,16),(13,17),(14,18)]:
                d[a], d[b] = c[b], c[a]
            tc.append(d)
    elif mode==4:
        tc=[]
        for c in ctrls:
            d = c.copy()
            for a,b in [(0,5),(1,6),(2,7),(3,8),(4,9),(11,15),(12,16),(13,17),(14,18)]:
                d[a], d[b] = c[b], c[a]
            for idx in [0,1,2,5,6,7,10,12,13,16,17]:
                d[idx] = -d[idx]
            tc.append(d)
    else:
        tc=[]
        for c in ctrls[::-1]:
            d = c.copy()
            for a,b in [(0,5),(1,6),(2,7),(3,8),(4,9),(11,15),(12,16),(13,17),(14,18)]:
                d[a], d[b] = c[b], c[a]
            for idx in [0,1,2,5,6,7,10,12,13,16,17]:
                d[idx] = -d[idx]
            tc.append(d)
    transforms.append(tc)

for i,tc in enumerate(transforms):
    for rep in [1,2]:
        s=sim.Sim()
        for _ in range(rep):
            for ctrl,st in zip(tc,steps):
                s.data.ctrl[:] = ctrl
                s.step(st)
        print('mode',i,'rep',rep,'px',s.pelvis_position()[0],'bx',s.box_position()[0],'pz',s.pelvis_position()[2],'tu',s.torso_up())
PY"

